<section class="section container search-page"><?php breadcrumbs(['Поиск'=>null]) ?><span class="eyebrow">По каталогу продукции</span><h1><?= e($page['h1']) ?></h1><p class="lead"><?= e($page['lead']) ?></p><form class="search-box search-box-large" method="get" action="<?= url('/search') ?>"><span aria-hidden="true">⌕</span><input type="search" name="q" value="<?= e($q) ?>" placeholder="Например, ВВГнг, арматура или ТМГ" aria-label="Поиск по каталогу" maxlength="120" required><button class="btn btn-primary" type="submit">Найти</button></form><div class="filter-pills"><?php foreach(roots() as $c): ?><a href="<?= url('/catalog/'.$c['slug']) ?>"><?= e($c['name']) ?></a><?php endforeach ?></div></section>
<section class="section container"><?php if($q===''): ?><article class="detail-card prose"><?= rich($page['body_html']) ?></article><?php elseif(!$products): ?><div class="empty-state"><h2>По запросу «<?= e($q) ?>» ничего не найдено</h2><p>Проверьте маркировку или отправьте запрос менеджеру: можно указать любую позицию вручную.</p><a class="btn btn-primary" href="<?= url('/request') ?>">Отправить запрос</a></div><?php else: ?><div class="section-head"><h2>Найдено <?= (int)$total ?> позиций</h2></div><div class="product-grid"><?php foreach($products as $p)product_card($p) ?></div><?php if($lastPage>1): ?><nav class="pagination" aria-label="Страницы результатов"><?php for($i=max(1,$currentPage-2);$i<=min($lastPage,$currentPage+2);$i++): ?><a <?= $i===$currentPage?'aria-current="page"':'' ?> href="<?= e(url('/search').'?'.http_build_query(['q'=>$q,'page'=>$i])) ?>"><?= $i ?></a><?php endfor ?></nav><?php endif;endif ?></section>
